CREATE TABLE IF NOT EXISTS request_cancellation (id CHAR(36) PRIMARY KEY, request_id CHAR(36) NOT NULL, actor_person_id CHAR(36) NOT NULL, reason VARCHAR(2048) NOT NULL, created_at DATETIME NOT NULL, KEY request_cancellation_request_index (request_id), CONSTRAINT request_cancellation_request_fk FOREIGN KEY (request_id) REFERENCES request(id), CONSTRAINT request_cancellation_actor_fk FOREIGN KEY (actor_person_id) REFERENCES person(id));
